=== FILE: uart_tx_rootcause_repro.v ===
// Root-cause repro for the uart_tx regression failure.
// Specified behaviour (from the uart_tx header): 8N1 framing -- one start bit
// (low), eight data bits LSB first, one stop bit (high), each CLKS_PER_BIT
// clocks long; a start pulse while a frame is in flight is ignored.
// The test sends 0xA5, pulses start with 0x3C in the middle of data bit 2,
// and expects 0xA5 on the line. Expected values come from the specification,
// not from any implementation's output. Only ports are used.
`timescale 1ns / 1ps
module uart_tx_rootcause_repro_tb;
    localparam integer CPB      = 4;
    localparam integer CLK_HALF = 5;
    localparam integer CLK_NS   = 2 * CLK_HALF;
    localparam integer BIT_NS   = CPB * CLK_NS;

    reg        clk   = 1'b0;
    reg        rst   = 1'b1;
    reg        start = 1'b0;
    reg  [7:0] data  = 8'h00;
    wire       tx;
    wire       busy;

    integer n_pass = 0;
    integer n_fail = 0;
    reg     verdict_done = 1'b0;
    reg [8*128-1:0] nonce;

    reg  [7:0] rx_byte;
    reg        rx_start_bit;
    reg        rx_stop_bit;
    reg        rx_ok;
    integer    k;

    uart_tx #(.CLKS_PER_BIT(CPB)) dut (
        .clk   (clk),
        .rst   (rst),
        .start (start),
        .data  (data),
        .tx    (tx),
        .busy  (busy)
    );

    always #CLK_HALF clk = ~clk;

    task check(input cond, input [8*64-1:0] what);
        begin
            if (cond) begin
                n_pass = n_pass + 1;
                $display("check PASS: %0s", what);
            end else begin
                n_fail = n_fail + 1;
                $display("check FAIL: %0s", what);
            end
        end
    endtask

    task print_verdict;
        begin
            if (!verdict_done) begin
                verdict_done = 1'b1;
                $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, n_pass, n_fail);
            end
        end
    endtask

    // Wait for the start-bit falling edge, with a timeout.
    task wait_tx_fall(output ok);
        begin
            ok = 1'b0;
            fork : wf
                begin
                    @(negedge tx);
                    ok = 1'b1;
                    disable wf;
                end
                begin
                    #(30 * BIT_NS);
                    disable wf;
                end
            join
        end
    endtask

    // Receive one frame by sampling mid-bit (on a negative clock edge).
    // If inject is set, pulse start with inj_data for one clock in the
    // middle of data bit 2.
    task rx_frame(input inject, input [7:0] inj_data,
                  output [7:0] d, output s, output p, output ok);
        begin
            d = 8'h00;
            s = 1'b1;
            p = 1'b0;
            wait_tx_fall(ok);
            if (ok) begin
                fork
                    begin
                        #(BIT_NS / 2 - CLK_HALF);
                        s = tx;
                        for (k = 0; k < 8; k = k + 1) begin
                            #(BIT_NS);
                            d[k] = tx;
                        end
                        #(BIT_NS);
                        p = tx;
                    end
                    begin
                        if (inject) begin
                            #(BIT_NS / 2 - CLK_HALF + 3 * BIT_NS);
                            data  = inj_data;
                            start = 1'b1;
                            #(CLK_NS);
                            start = 1'b0;
                        end
                    end
                join
            end
        end
    endtask

    initial begin
        if (!$value$plusargs("NIRMAAN_NONCE=%s", nonce))
            if (!$value$plusargs("nirmaan_nonce=%s", nonce))
                if (!$value$plusargs("NONCE=%s", nonce))
                    if (!$value$plusargs("nonce=%s", nonce))
                        nonce = "none";

        rst = 1'b1;
        repeat (4) @(posedge clk);
        @(negedge clk);
        rst = 1'b0;
        repeat (3) @(negedge clk);
        check(tx === 1'b1, "tx idles high after reset");

        // Frame 1: 0xA5, with a start pulse carrying 0x3C mid-frame.
        fork
            rx_frame(1'b1, 8'h3C, rx_byte, rx_start_bit, rx_stop_bit, rx_ok);
            begin
                @(negedge clk);
                data  = 8'hA5;
                start = 1'b1;
                @(negedge clk);
                start = 1'b0;
            end
        join
        check(rx_ok && (rx_start_bit === 1'b0), "frame 1 start bit is low");
        check(rx_ok && (rx_byte === 8'hA5),
              "frame 1 byte is 0xA5; mid-frame start pulse ignored");
        if (rx_ok && rx_byte !== 8'hA5)
            $display("  frame 1 received 0x%02h, expected 0xA5", rx_byte);
        check(rx_ok && (rx_stop_bit === 1'b1), "frame 1 stop bit is high");

        // Let the line return to idle.
        repeat (3 * CPB) @(negedge clk);

        // Frame 2: 0x3C sent normally from idle.
        fork
            rx_frame(1'b0, 8'h00, rx_byte, rx_start_bit, rx_stop_bit, rx_ok);
            begin
                @(negedge clk);
                data  = 8'h3C;
                start = 1'b1;
                @(negedge clk);
                start = 1'b0;
            end
        join
        check(rx_ok && (rx_byte === 8'h3C) && (rx_stop_bit === 1'b1),
              "frame 2 byte is 0x3C with a high stop bit");

        repeat (2 * CPB) @(negedge clk);
        print_verdict;
        $finish;
    end

    // Watchdog: guarantees exactly one verdict line even if the test hangs.
    initial begin
        #(200 * BIT_NS);
        if (!verdict_done) begin
            n_fail = n_fail + 1;
            $display("check FAIL: watchdog timeout");
            print_verdict;
            $finish;
        end
    end
endmodule
=== END FILE ===
